<style>:root{--gold:#f0a629;--ink:#191a1d;--muted:#687078;--wide:min(1280px,calc(100% - 48px))}*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;color:var(--ink);line-height:1.5}a{text-decoration:none;color:inherit}button,input,textarea{font:inherit}.xd5-container{width:var(--wide);margin:auto}.xd5-header{position:absolute;z-index:9;width:100%;color:#fff;background:#18191bbd}.xd5-utility{border-bottom:1px solid #ffffff1f;font-size:12px}.xd5-utility>div{display:flex;justify-content:flex-end;gap:34px;padding:11px 0}.xd5-nav-wrap{display:flex;align-items:center;min-height:88px;gap:28px}.xd5-brand{display:flex;align-items:center;gap:9px;font-size:27px;font-weight:800}.xd5-brand span{color:var(--gold);font-size:39px}.xd5-brand img{display:block;max-width:240px;max-height:72px;object-fit:contain}.xd5-nav-wrap>button{display:none}.xd5-nav-wrap nav{display:flex;flex:1;justify-content:center;gap:31px;font-size:14px;font-weight:700;text-transform:uppercase}.xd5-hotline{font-size:22px;font-weight:700}.xd5-hero{position:relative;min-height:720px;overflow:hidden;background:#333;color:#fff}.xd5-hero__slide{position:absolute;inset:0;opacity:0;transition:.4s}.xd5-hero__slide.is-active{opacity:1}.xd5-hero img{width:100%;height:100%;object-fit:cover}.xd5-veil{position:absolute;inset:0;background:#0007}.xd5-hero-copy{position:relative;z-index:1;display:flex;min-height:720px;align-items:center}.xd5-hero-copy>div{max-width:600px;margin-top:90px}.xd5-kicker{color:var(--gold);font-weight:700}.xd5-hero h1,.xd5-title{margin:12px 0;font-size:clamp(37px,4.5vw,62px);line-height:1.12}.xd5-hero p{font-size:17px}.xd5-btn{display:inline-flex;padding:13px 24px;background:var(--gold);color:#fff;font-weight:700}.xd5-section{padding:92px 0}.xd5-eyebrow{margin:0;color:var(--gold);font-weight:700}.xd5-title{font-size:42px}.xd5-services{display:grid;grid-template-columns:repeat(4,1fr);gap:30px;margin-top:54px}.xd5-service{display:grid;min-height:380px;grid-template-rows:auto 1fr auto;border-top:3px solid var(--gold);padding:25px;background:#fff;box-shadow:0 16px 35px #1111}.xd5-service h3{font-size:20px}.xd5-service p{color:var(--muted)}.xd5-service img{width:100%;height:165px;object-fit:cover}.xd5-about{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center}.xd5-about-media{position:relative;min-height:450px}.xd5-about-media img{width:72%;height:415px;object-fit:cover}.xd5-about-badge{position:absolute;right:0;bottom:0;width:48%;padding:35px;background:#191a1de8;color:#fff;text-align:center}.xd5-about-badge b{font-size:48px}.xd5-progress{height:8px;background:#ebedf0}.xd5-progress i{display:block;height:100%;background:var(--gold)}.xd5-benefits,.xd5-contact{background:#151618;color:#fff}.xd5-benefit-grid{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}.xd5-benefit-grid img{width:100%;height:530px;object-fit:cover}.xd5-benefit-list{display:grid;grid-template-columns:1fr 1fr;gap:25px;margin-top:55px}.xd5-benefit-list b{display:flex;align-items:center;gap:12px}.xd5-benefit-list b:before{display:grid;width:45px;height:45px;place-items:center;background:var(--gold);color:#18191b;content:'Ã¢Å“â€œ'}.xd5-testimonial{background:#fafafa}.xd5-testimonial-grid{display:grid;grid-template-columns:1fr repeat(3,1fr);gap:24px;align-items:stretch}.xd5-testimonial-copy{padding:25px 0}.xd5-quote{padding:30px;background:#fff;box-shadow:0 12px 30px #1111}.xd5-quote img{width:56px;height:56px;border-radius:50%;object-fit:cover}.xd5-team-head{text-align:center}.xd5-team{display:grid;grid-template-columns:repeat(3,1fr);gap:36px;margin-top:50px}.xd5-team article{overflow:hidden;border-radius:0 48px 0 48px;background:#191a1d;color:#fff;text-align:center}.xd5-team img{display:block;width:100%;height:410px;object-fit:cover}.xd5-team h3{margin:20px 0 0}.xd5-team p{margin:4px 0 22px}.xd5-contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:95px;align-items:center}.xd5-contact-info{display:grid;gap:24px;margin-top:45px}.xd5-contact-info b{display:block;color:var(--gold)}.xd5-contact-card{padding:46px;background:#fff;color:var(--ink);border-radius:18px}.xd5-contact-card h2{text-align:center;font-size:38px}.xd5-contact-card input,.xd5-contact-card textarea{width:100%;margin:8px 0;padding:17px;border:0;background:#f0f1f4}.xd5-posts{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;margin-top:45px}.xd5-post{box-shadow:0 12px 35px #1111}.xd5-post img{width:100%;height:270px;object-fit:cover}.xd5-post div{padding:25px}.xd5-partners{padding:66px 0}.xd5-partner-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:25px}.xd5-partner{display:grid;min-height:90px;place-items:center}.xd5-partner img{max-width:180px;max-height:75px;object-fit:contain}.xd5-footer{padding:55px 0;background:#1d1e21;color:#fff}.xd5-footer-top{display:flex;justify-content:space-between;align-items:center;padding-bottom:35px;border-bottom:1px solid #ffffff22}.xd5-footer-top small{display:block;color:var(--gold)}.xd5-footer-top b{font-size:22px}.xd5-footer-grid{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:80px;padding-top:35px}.xd5-footer p{color:#d9d9dc}.xd5-footer ul{padding:0;list-style:none}.xd5-footer li{margin:10px 0}.xd5-footer form{display:grid;grid-template-columns:1fr auto}.xd5-footer input{min-width:0;padding:13px;border:0}.xd5-footer button{border:0;background:var(--gold);color:#fff;padding:0 18px}@media(max-width:900px){.xd5-nav-wrap nav{gap:15px}.xd5-services,.xd5-team{grid-template-columns:repeat(2,1fr)}.xd5-about,.xd5-benefit-grid,.xd5-contact-grid{grid-template-columns:1fr}.xd5-posts{grid-template-columns:1fr}.xd5-partner-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:620px){:root{--wide:min(100% - 30px,1280px)}.xd5-utility{display:none}.xd5-header{position:relative;background:#18191b}.xd5-nav-wrap{min-height:70px}.xd5-nav-wrap>button{display:block;margin-left:auto;background:transparent;border:1px solid #fff6;color:#fff;padding:8px}.xd5-nav-wrap nav{display:none;flex-basis:100%;order:3;flex-direction:column;align-items:flex-start;padding-bottom:16px}.xd5-nav-wrap nav.is-open{display:flex}.xd5-hotline{display:none}.xd5-hero,.xd5-hero-copy{min-height:560px}.xd5-hero h1{font-size:39px}.xd5-services,.xd5-testimonial-grid,.xd5-team,.xd5-benefit-list,.xd5-footer-grid{grid-template-columns:1fr}.xd5-section{padding:65px 0}.xd5-about-media img{width:100%}.xd5-about-badge{right:10px}.xd5-partner-grid{grid-template-columns:repeat(2,1fr)}.xd5-footer-top{display:grid;gap:20px}}</style>
